const std = @import("std");
const depth = @import("depth");
fn noCopy(_: *anyopaque, _: *const depth.Who) bool { return false; }
pub fn main() !void {
    const gpa = std.heap.page_allocator;
    var slots = [_]?f64{ null, 10, 11 };
    const holds = [_]depth.HoldCost{.{ .streams = 1, .depth = 1, .ms = 5 }};
    for ([_]bool{false, true}) |sampled| {
        var rule: depth.Rule = .{ .gpa = gpa, .k = .{ .hold_costs = &holds, .depth_rate = 0.5, .grant_slack = 0 }, .prior = &.{0.95}, .most_drafts = 1, .family_costs = &.{}, .shared_costs = &.{ .slots = &slots }, .mtp_step_ms = 1, .plain_guard = true, .node_probabilities = true, .granted_depth = true, .batch_rows = 32 };
        defer rule.deinit();
        var state: ?depth.State = null;
        defer if (state) |*s| s.deinit(gpa);
        var whos = [_]depth.Who{.{ .state = &state, .draft_room = 32, .finished = false, .forced = false, .granted = 1, .gain = 0.99, .sampled = sampled }};
        var unused: u8 = 0;
        const probe: depth.Probe = .{ .ptr = &unused, .copy = noCopy };
        try rule.observeOverhead(1, 2, 16, sampled, rule.headMs(&.{1}));
        var skipped: usize = 0;
        var later_trials: usize = 0;
        var streak: usize = 0;
        for (0..200) |round| {
            var out: [1]i64 = undefined;
            try rule.budgets(&whos, probe, sampled, &out);
            if (out[0] == 0) { skipped += 1; streak = 0; continue; }
            const success = round >= 16;
            try rule.observeDepth(whos[0], 1, @intFromBool(success));
            if (success) { later_trials += 1; streak += 1; }
        }
        std.debug.print("sampled={} skipped={d} actual_later_trials={d} final_held_streak={d}\n", .{sampled, skipped, later_trials, streak});
        if (skipped == 0 or later_trials == 0 or streak < 8) return error.HoldNeverRecovered;
    }
}
